// Video #1 — "The real cost of a $5 coffee"
// Numbers come from coffee.data.json (generated by calc/coffee.py): $5/day = $152.08/month,
// 7% a year compounded monthly, 30 years.
import {Recipe} from '../template';
import data from '../coffee.data.json';
import tCoffee from './Coffee.timing.json';

const spent = data.cash['30'];
const invested = data.invested['30'];
const fmt = (n: number) => '$' + n.toLocaleString('en-US');

const base: Recipe = {
  id: 'Coffee',
  thumb: {kicker: 'THE REAL COST OF', from: '$5 coffee', link: 'really costs', to: '$185,537', foot: 'over 30 years'},
  channel: 'MONEY, IN DATA',
  // Scene lengths and cues are timed to the voice-over (word timings in calc/coffee-words.json).
  scenes: [
    {type: 'hook', dur: 225, cues: [41, 83, 113, 159], kicker: '$5 a day', lines: ['One coffee.', '*$5. Every day.*', 'For 30 years.'], question: 'What does it really cost?'},
    {
      type: 'people', dur: 285, cues: [60, 114, 216], kicker: 'Two choices', footnote: 'Same money. Different choice.',
      people: [
        {name: 'Jordan', color: 'paper', tag: 'BUYS THE COFFEE', note: '$5 a day, every day, for 30 years.', statLabel: 'SPENT', stat: fmt(spent)},
        {name: 'Riley', color: 'accent', tag: 'INVESTS THE $5', note: 'Puts the same ~$152 a month into investments.', statLabel: 'PUT IN', stat: fmt(spent)},
      ],
    },
    {
      type: 'race', dur: 315, cues: [10, 300], kicker: 'Watch the gap', xLabel: 'YEARS', xStart: 0, xEnd: 30, xTicks: [0, 10, 20, 30],
      yMax: 200000, yTicks: [0, 50000, 100000, 150000, 200000],
      series: [
        {name: 'Riley invested', color: 'accent', data: data.invested},
        {name: 'Jordan spent', color: 'paper', data: data.cash},
      ],
      notes: [
        {at: 8, text: 'Early on, barely any difference', x: 1, yValue: 170000, color: 'muted'},
        {at: 19, text: 'Year 19: growth overtakes\nwhat Riley put in', x: 1, yValue: 125000, color: 'accent'},
      ],
    },
    {
      type: 'reveal', dur: 450, cues: [45, 192, 297], kicker: 'After 30 years',
      items: [
        {label: 'JORDAN · SPENT ON COFFEE', value: fmt(spent), color: 'paper'},
        {label: 'RILEY · INVESTED', value: fmt(invested), color: 'accent'},
      ],
      punch: `Same $5 a day.\n*${fmt(invested - spent)} apart.*`,
    },
    {
      type: 'bars', dur: 216, cues: [9, 30, 90], kicker: 'Where it came from', title: 'Most of it is *growth.*', max: 200000,
      bars: [
        {label: 'Riley', color: 'accent', base: spent, extra: invested - spent, caption: `${fmt(spent)} in · ${fmt(invested - spent)} growth`},
        {label: 'Jordan', color: 'paper', base: spent, extra: 0, caption: `${fmt(spent)} spent · $0 left`},
      ],
      body: 'Riley never earned more than Jordan.\n*Time* did the heavy lifting.',
    },
    {
      type: 'outro', dur: 174, cues: [3, 100], lines: 'Enjoy the coffee.\nJust know its *real price.*',
      disclaimer: 'Illustration only: assumes a steady 7% yearly return,\ncompounded monthly, before fees, tax and inflation.\nReal returns vary. Not financial advice.',
    },
  ],
};
export const coffee: Recipe = {...base, audio: 'audio/Coffee.mp3', scenes: base.scenes.map((s, i) => ({...s, ...tCoffee[i]}))};
